        // ---- Превью для клиента: 2D план и реалистичный 3D (Three.js, вид снизу) ----
        let _clientPreviewMode = '2d';
        let _three = null;
        let _threeScene = null;
        let _threeRenderer = null;
        let _threeCamera = null;
        let _threeAnim = null;
        let _threeDrag = null;
        let _threeRenderFrame = null;
        let _threePostDispose = null;
        // Фото реальной комнаты → текстуры пола/стен в 3D
        let roomPhotoImg = null;
        let roomPhotoUrl = null;
        let preferredCurtainColor = '#c4b5a0';
        let preferredWallColor = null;  // null = текстура по умолчанию / фото
        let preferredFloorColor = null;
        let roomHeightM = 2.7;          // высота потолка, м (регулируется в 3D)
        // Логотип/бренд для картины над диваном и рекламного экрана ТВ в 3D-туре
        const BOT_LOGO_DATAURL = "data:image/jpeg;base64,";
        let _maxAniso = 4;              // анизотропия текстур (из renderer.capabilities)
        let _glowTexCache = null;

        /** Общая настройка канвас-текстуры: sRGB, тайлинг, анизотропия. */
        function tuneTex(THREE, tex, repX, repY) {
            if (!tex) return tex;
            if (THREE.sRGBEncoding) tex.encoding = THREE.sRGBEncoding;
            if (tex.colorSpace !== undefined && THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
            tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
            tex.repeat.set(repX == null ? 1 : repX, repY == null ? 1 : repY);
            tex.anisotropy = _maxAniso;
            tex.generateMipmaps = true;
            tex.minFilter = THREE.LinearMipmapLinearFilter;
            tex.magFilter = THREE.LinearFilter;
            tex.needsUpdate = true;
            return tex;
        }

        /** Мягкое радиальное свечение — ореолы светильников, световые пятна. */
        function makeGlowTexture(THREE) {
            if (_glowTexCache) return _glowTexCache;
            const c = document.createElement('canvas');
            c.width = c.height = 128;
            const g = c.getContext('2d');
            const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
            grd.addColorStop(0, 'rgba(255,255,255,1)');
            grd.addColorStop(0.35, 'rgba(255,245,220,0.55)');
            grd.addColorStop(0.7, 'rgba(255,240,210,0.16)');
            grd.addColorStop(1, 'rgba(255,240,210,0)');
            g.fillStyle = grd;
            g.fillRect(0, 0, 128, 128);
            _glowTexCache = new THREE.CanvasTexture(c);
            if (THREE.sRGBEncoding) _glowTexCache.encoding = THREE.sRGBEncoding;
            _glowTexCache.generateMipmaps = true;
            _glowTexCache.minFilter = THREE.LinearMipmapLinearFilter;
            _glowTexCache.magFilter = THREE.LinearFilter;
            _glowTexCache.anisotropy = _maxAniso;
            return _glowTexCache;
        }

        function triggerRoomPhotoCapture() {
            const inp = document.getElementById('room-photo-input');
            if (inp) inp.click();
        }

        function clearRoomPhoto() {
            if (roomPhotoUrl) {
                try { URL.revokeObjectURL(roomPhotoUrl); } catch (e) {}
            }
            roomPhotoUrl = null;
            roomPhotoImg = null;
            const btn = document.getElementById('btn-clear-room-photo');
            if (btn) btn.style.display = 'none';
            showToast('Фото комнаты сброшено', 1800);
        }

        function onRoomPhotoSelected(ev) {
            const file = ev && ev.target && ev.target.files && ev.target.files[0];
            if (!file) return;
            if (roomPhotoUrl) {
                try { URL.revokeObjectURL(roomPhotoUrl); } catch (e) {}
            }
            roomPhotoUrl = URL.createObjectURL(file);
            const img = new Image();
            img.onload = function () {
                roomPhotoImg = img;
                const btn = document.getElementById('btn-clear-room-photo');
                if (btn) btn.style.display = 'block';
                showToast('Цвет обоев и пола с фото применены — откройте 3D', 2800);
                // если 3D уже открыт — пересобрать сцену
                const d3 = document.getElementById('client-preview-3d');
                if (d3 && d3.style.display !== 'none' && _clientPreviewMode === '3d') {
                    renderClient3DRealistic().catch(function () {});
                }
            };
            img.onerror = function () {
                showToast('Не удалось загрузить фото', 2500);
            };
            img.src = roomPhotoUrl;
            try { ev.target.value = ''; } catch (e) {}
        }

        /**
         * Фото комнаты → только цвет/фактура обоев, цвет пола, намёк где окно.
         * Целиком фото на стены не клеим.
         */
        function analyzeRoomPhoto() {
            if (!roomPhotoImg || !roomPhotoImg.width) return null;
            const iw = roomPhotoImg.width, ih = roomPhotoImg.height;
            const c = document.createElement('canvas');
            const maxW = 160;
            const sc = maxW / iw;
            c.width = maxW;
            c.height = Math.max(1, Math.round(ih * sc));
            const g = c.getContext('2d');
            g.drawImage(roomPhotoImg, 0, 0, c.width, c.height);
            const w = c.width, h = c.height;
            const data = g.getImageData(0, 0, w, h).data;

            function avgRegion(x0, y0, x1, y1) {
                x0 = Math.max(0, Math.floor(x0)); y0 = Math.max(0, Math.floor(y0));
                x1 = Math.min(w, Math.ceil(x1)); y1 = Math.min(h, Math.ceil(y1));
                let r = 0, gg = 0, b = 0, n = 0;
                for (let y = y0; y < y1; y++) {
                    for (let x = x0; x < x1; x++) {
                        const i = (y * w + x) * 4;
                        r += data[i]; gg += data[i + 1]; b += data[i + 2]; n++;
                    }
                }
                if (!n) return { r: 200, g: 190, b: 175 };
                return { r: Math.round(r / n), g: Math.round(gg / n), b: Math.round(b / n) };
            }

            const wallColor = avgRegion(w * 0.1, h * 0.2, w * 0.9, h * 0.55);
            const floorColor = avgRegion(w * 0.15, h * 0.65, w * 0.85, h * 0.95);

            let bestWin = { score: -1, side: 'right', t: 0.5 };
            [
                { side: 'left', x0: 0, y0: h * 0.15, x1: w * 0.2, y1: h * 0.55 },
                { side: 'right', x0: w * 0.8, y0: h * 0.15, x1: w, y1: h * 0.55 },
                { side: 'top', x0: w * 0.2, y0: 0, x1: w * 0.8, y1: h * 0.22 }
            ].forEach(band => {
                const col = avgRegion(band.x0, band.y0, band.x1, band.y1);
                const lum = 0.299 * col.r + 0.587 * col.g + 0.114 * col.b;
                const score = lum + Math.max(0, col.b - col.r) * 0.3;
                if (score > bestWin.score) bestWin = { score, side: band.side, t: 0.5, color: col };
            });

            // Небольшой патч для фактуры обоев (не целое фото)
            const patC = document.createElement('canvas');
            patC.width = 128; patC.height = 128;
            const pg = patC.getContext('2d');
            pg.drawImage(roomPhotoImg, iw * 0.25, ih * 0.25, iw * 0.5, ih * 0.3, 0, 0, 128, 128);
            pg.fillStyle = `rgba(${wallColor.r},${wallColor.g},${wallColor.b},0.55)`;
            pg.fillRect(0, 0, 128, 128);

            return { wallColor, floorColor, windowHint: bestWin, patternCanvas: patC };
        }

        function makeTexturesFromRoomPhoto(THREE) {
            const info = analyzeRoomPhoto();
            if (!info) return null;
            const { wallColor, floorColor, windowHint, patternCanvas } = info;
            const fr = floorColor.r, fg0 = floorColor.g, fb = floorColor.b;

            // Ламинат, тонированный цветом пола с фото
            const floorC = document.createElement('canvas');
            floorC.width = 512; floorC.height = 512;
            const fctx = floorC.getContext('2d');
            fctx.fillStyle = `rgb(${fr},${fg0},${fb})`;
            fctx.fillRect(0, 0, 512, 512);
            const plankH = 64;
            for (let y = 0; y < 512; y += plankH) {
                const shade = 0.88 + ((y / plankH) % 3) * 0.04;
                fctx.fillStyle = `rgb(${Math.min(255, fr * shade) | 0},${Math.min(255, fg0 * shade) | 0},${Math.min(255, fb * shade) | 0})`;
                fctx.fillRect(0, y, 512, plankH - 2);
                for (let i = 0; i < 12; i++) {
                    fctx.strokeStyle = `rgba(0,0,0,${0.04 + Math.random() * 0.05})`;
                    fctx.beginPath();
                    const yy = y + 6 + Math.random() * (plankH - 12);
                    fctx.moveTo(0, yy);
                    fctx.lineTo(512, yy + (Math.random() - 0.5) * 5);
                    fctx.stroke();
                }
                fctx.fillStyle = 'rgba(0,0,0,0.2)';
                fctx.fillRect(0, y + plankH - 2, 512, 2);
                for (let x = ((y / plankH) % 2) * 80; x < 512; x += 160) {
                    fctx.fillStyle = 'rgba(0,0,0,0.14)';
                    fctx.fillRect(x, y, 2, plankH - 2);
                }
            }
            const floorTex = new THREE.CanvasTexture(floorC);
            tuneTex(THREE, floorTex, 4, 4);

            // Обои: цвет стен + лёгкая фактура с фото
            const wallC = document.createElement('canvas');
            wallC.width = 256; wallC.height = 256;
            const wctx = wallC.getContext('2d');
            wctx.fillStyle = `rgb(${wallColor.r},${wallColor.g},${wallColor.b})`;
            wctx.fillRect(0, 0, 256, 256);
            if (patternCanvas) {
                wctx.globalAlpha = 0.32;
                for (let yy = 0; yy < 256; yy += 128) {
                    for (let xx = 0; xx < 256; xx += 128) wctx.drawImage(patternCanvas, xx, yy);
                }
                wctx.globalAlpha = 1;
            }
            // мягкий шум вместо клетчатой сетки — стена выглядит как обои, а не как миллиметровка
            const wImg = wctx.getImageData(0, 0, 256, 256);
            const wd = wImg.data;
            for (let i = 0; i < wd.length; i += 4) {
                const n = (Math.random() - 0.5) * 12;
                wd[i] += n; wd[i + 1] += n; wd[i + 2] += n;
            }
            wctx.putImageData(wImg, 0, 0);
            const wallTex = new THREE.CanvasTexture(wallC);
            tuneTex(THREE, wallTex, 1, 1);

            return { floorTex, wallTex, windowHint, wallColor, floorColor };
        }

        /** Стили оверлея 3D: стеклянная панель, «пилюли», джойстик. */
