            function dataUrlToBlob(dataUrl) {
                var parts = dataUrl.split(',');
                var mime = (parts[0].match(/:(.*?);/) || [])[1] || 'image/jpeg';
                var bin = atob(parts[1] || '');
                var arr = new Uint8Array(bin.length);
                for (var i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
                return new Blob([arr], { type: mime });
            }

            function compressDataUrl(dataUrl, maxSide, quality) {
                return new Promise(function (resolve) {
                    try {
                        var img = new Image();
                        img.onload = function () {
                            var w = img.width || 1, h = img.height || 1;
                            var scale = 1;
                            if (w > maxSide || h > maxSide) scale = Math.min(maxSide / w, maxSide / h);
                            var tc = document.createElement('canvas');
                            tc.width = Math.max(1, Math.round(w * scale));
                            tc.height = Math.max(1, Math.round(h * scale));
                            var ctx = tc.getContext('2d');
                            ctx.drawImage(img, 0, 0, tc.width, tc.height);
                            resolve(tc.toDataURL('image/jpeg', quality));
                        };
                        img.onerror = function () { resolve(dataUrl); };
                        img.src = dataUrl;
                    } catch (e) { resolve(dataUrl); }
                });
            }

            async function uploadKpImage(dataUrl) {
                var blob = dataUrlToBlob(dataUrl);
                // Только хосты, которые отдают ПРЯМУЮ ссылку на файл (не HTML-страницу).
                // tmpfiles.org убран — отдаёт HTML, бот не может вставить в КП.
                var hosts = [
                    async function () {
                        var fd = new FormData();
                        fd.append('reqtype', 'fileupload');
                        fd.append('fileToUpload', blob, 'kp_potolok.jpg');
                        var r = await fetch('https://catbox.moe/user/api.php', { method: 'POST', body: fd });
                        var t = (await r.text()).trim();
                        if (t && /^https?:\/\/files\.catbox\.moe\//i.test(t)) return t;
                        if (t && /^https?:\/\//i.test(t) && t.length < 200 && t.indexOf('tmpfiles') < 0) return t;
                        return null;
                    },
                    async function () {
                        var fd = new FormData();
                        fd.append('reqtype', 'fileupload');
                        fd.append('time', '72h');
                        fd.append('fileToUpload', blob, 'kp_potolok.jpg');
                        var r = await fetch('https://litterbox.catbox.moe/resources/internals/api.php', { method: 'POST', body: fd });
                        var t = (await r.text()).trim();
                        if (t && /^https?:\/\//i.test(t) && t.length < 200 && t.indexOf('tmpfiles') < 0) return t;
                        return null;
                    },
                    async function () {
                        var fd = new FormData();
                        fd.append('file', blob, 'kp.jpg');
                        var r = await fetch('https://0x0.st', { method: 'POST', body: fd });
                        var t = (await r.text()).trim();
                        if (t && /^https?:\/\//i.test(t) && t.length < 200) return t;
                        return null;
                    }
                ];
                for (var i = 0; i < hosts.length; i++) {
                    try {
                        var u = await hosts[i]();
                        if (u) return u;
                    } catch (e) { console.warn('upload host', i, e); }
                }
                return null;
            }

async function captureCeilingPhotoForKP() {
                if (!renderer || !scene || !camera) {
                    showToast('3D не готово', 2000);
                    return;
                }
                kpPhotoBtn.disabled = true;
                kpPhotoBtn.textContent = '⏳ Съёмка…';
                try { if (typeof goCeilingOverviewCam === 'function') goCeilingOverviewCam(); } catch (e0) {}
                for (var i = 0; i < 4; i++) {
                    try {
                        if (typeof stepCam === 'function') stepCam(0.05);
                        if (typeof applyCam === 'function') applyCam();
                        if (typeof renderFrame === 'function') renderFrame();
                        else renderer.render(scene, camera);
                    } catch (e1) {}
                }
                await new Promise(function (r) { setTimeout(r, 80); });
                var dataUrl = '';
                try {
                    dataUrl = renderer.domElement.toDataURL('image/jpeg', 0.88);
                } catch (e2) {
                    showToast('Ошибка снимка 3D', 2500);
                    kpPhotoBtn.disabled = false;
                    kpPhotoBtn.textContent = '📷 Фото для КП';
                    return;
                }
                if (!dataUrl || dataUrl.length < 500) {
                    showToast('Пустой снимок', 2000);
                    kpPhotoBtn.disabled = false;
                    kpPhotoBtn.textContent = '📷 Фото для КП';
                    return;
                }
                // Сжимаем (не сохраняем на телефон — только в память для КП)
                dataUrl = await compressDataUrl(dataUrl, 1200, 0.75);
                // ультра-сжатие для встраивания в sendData (если хостинг недоступен)
                var dataUrlTiny = await compressDataUrl(dataUrl, 640, 0.55);
                var idx = (typeof editCeilingIndex === 'number' && editCeilingIndex >= 0)
                    ? editCeilingIndex
                    : (completedCeilings && completedCeilings.length) || 0;

                if (typeof window._kpPhotos !== 'object' || !window._kpPhotos) window._kpPhotos = {};
                // Сразу кладём (полное + потом подожмём при отправке)
                window._kpPhotos[idx] = dataUrl;
                try {
                    if (typeof dataUrlTiny === 'string' && dataUrlTiny.length > 100) {
                        // tiny как запасной
                        window._kpPhotos['t' + idx] = dataUrlTiny;
                    }
                } catch (eTinyStore) {}
                try {
                    if (completedCeilings && completedCeilings[idx]) {
                        completedCeilings[idx].kp_photo = dataUrl;
                        completedCeilings[idx].kp_photo_url = dataUrl;
                    }
                } catch (e3) {}

                kpPhotoBtn.textContent = '⏳ В КП…';
                showToast('Снимок сделан — отправляю в КП…', 2000);
                var url = await uploadKpImage(dataUrl);
                if (url) {
                    window._kpPhotos[idx] = url;
                    try {
                        if (completedCeilings && completedCeilings[idx]) {
                            completedCeilings[idx].kp_photo = url;
                            completedCeilings[idx].kp_photo_url = url;
                        }
                    } catch (e4) {}
                    try {
                        var store = {};
                        Object.keys(window._kpPhotos).forEach(function (k) {
                            var v = window._kpPhotos[k];
                            if (typeof v === 'string' && v.indexOf('http') === 0) store[k] = v;
                        });
                        localStorage.setItem('zamer_kp_photos_v1', JSON.stringify(store));
                    } catch (e5) {}
                    showToast('✅ Фото потолка №' + (idx + 1) + ' в КП (не на телефон)', 3500);
                } else {
                    // dataURL остаётся в памяти и уйдёт в бот вместе с чертежом
                    if (typeof dataUrlTiny === 'string' && dataUrlTiny.length < 3200) {
                        window._kpPhotos[idx] = dataUrlTiny;
                        try {
                            if (completedCeilings && completedCeilings[idx]) {
                                completedCeilings[idx].kp_photo = dataUrlTiny;
                                completedCeilings[idx].kp_photo_url = dataUrlTiny;
                            }
                        } catch (eT) {}
                    }
                    showToast('✅ Фото №' + (idx + 1) + ' в КП (без хостинга, сжато)', 4000);
                }
                kpPhotoBtn.disabled = false;
                kpPhotoBtn.textContent = '📷 Фото ✓ №' + (idx + 1);
            }

            // Мебель — задаёт масштаб: без неё комната читается как коробка
